```typescript
function fordFulkerson(graph: number[][], source: number, sink: number): number {
    const parent = Array(graph.length).fill(-1);
    let maxFlow = 0;

    const bfs = (s: number, t: number, parent: number[]): boolean => {
        const visited = Array(graph.length).fill(false);
        const queue = [s];
        visited[s] = true;

        while (queue.length > 0) {
            const u = queue.shift()!;
            for (let v = 0; v < graph.length; v++) {
                if (!visited[v] && graph[u][v] > 0) {
                    queue.push(v);
                    visited[v] = true;
                    parent[v] = u;
                    if (v === t) return true;
                }
            }
        }
        return false;
    };

    while (bfs(source, sink, parent)) {
        let pathFlow = Infinity;
        let s = sink;
        while (s !== source) {
            pathFlow = Math.min(pathFlow, graph[parent[s]][s]);
            s = parent[s];
        }

        let v = sink;
        while (v !== source) {
            const u = parent[v];
            graph[u][v] -= pathFlow;
            graph[v][u] += pathFlow;
            v = u;
        }
        maxFlow += pathFlow;
    }
    return maxFlow;
}
