use std::collections::HashMap;

struct LRUCache {
    capacity: usize,
    map: HashMap<i32, i32>,
    queue: Vec<i32>,
}

impl LRUCache {
    fn new(capacity: usize) -> Self {
        LRUCache {
            capacity,
            map: HashMap::new(),
            queue: Vec::new(),
        }
    }

    fn get(&mut self, key: i32) -> i32 {
        if let Some(&value) = self.map.get(&key) {
            self.queue.remove(self.queue.iter().position(|&k| k == key).unwrap());
            self.queue.push(key);
            value
        } else {
            -1
        }
    }

    fn put(&mut self, key: i32, value: i32) {
        if self.map.contains_key(&key) {
            self.get(key);
        } else {
            if self.queue.len() == self.capacity {
                let lru = self.queue.remove(0);
                self.map.remove(&lru);
            }
            self.map.insert(key, value);
            self.queue.push(key);
        }
    }
}
