use std::collections::HashSet;

struct Graph {
    edges: Vec<(i32, i32)>,
}

impl Graph {
    fn new(edges: Vec<(i32, i32)>) -> Self {
        Graph { edges }
    }

    fn has_cycle(&self) -> bool {
        let mut visited = HashSet::new();
        for &node in self.edges.iter().map(|e| e.0) {
            if !visited.contains(&node) && self.dfs(node, &mut visited, -1) {
                return true;
            }
        }
        false
    }

    fn dfs(&self, node: i32, visited: &mut HashSet<i32>, parent: i32) -> bool {
        visited.insert(node);
        for &(neighbor, _) in self.edges.iter().filter(|e| e.0 == node) {
            if !visited.contains(&neighbor) {
                if self.dfs(neighbor, visited, node) {
                    return true;
                }
            } else if neighbor != parent {
                return true;
            }
        }
        false
    }
}
